          "selected_timeline_integrity_issue_count" => %{"type" => "integer", "minimum" => 0},
          "selected_timeline_integrity_issue_types" => %{
            "type" => "array",
            "items" => %{
              "type" => "string",
              "enum" => OrbitalDynamics.Timeline.capabilities().timeline_integrity_issue_types
            }
          },
          "selected_timeline_integrity_issues" => %{
            "type" => "array",
            "items" => %{"type" => "object"}
          },
          "selected_missing_dependency_activity_ids" => stable_id_array_schema(),
          "selected_missing_dependency_timeline_ids" => stable_id_array_schema(),
          "selected_self_dependency_activity_ids" => stable_id_array_schema(),
          "selected_self_dependency_timeline_ids" => stable_id_array_schema(),
          "selected_duplicate_dependency_activity_ids" => stable_id_array_schema(),
          "selected_duplicate_dependency_timeline_ids" => stable_id_array_schema(),
          "selected_duplicate_exclusivity_activity_ids" => stable_id_array_schema(),
          "selected_duplicate_exclusivity_timeline_ids" => stable_id_array_schema(),
          "selected_dependency_cycle_activity_ids" => stable_id_array_schema(),
          "selected_dependency_cycle_timeline_ids" => stable_id_array_schema(),
          "selected_dependency_order_violation_activity_ids" => stable_id_array_schema(),
          "selected_dependency_order_violation_timeline_ids" => stable_id_array_schema(),
          "selected_exclusivity_violation_activity_ids" => stable_id_array_schema(),
          "selected_exclusivity_violation_timeline_ids" => stable_id_array_schema(),
          "selected_exclusivity_violation_group" => %{"type" => "string"},
          "source_timeline_diff_summary" => timeline_diff_summary_source_json_schema(),
          "source_timeline_transition_application_summary" =>
            timeline_transition_application_summary_source_json_schema(),
          "source_timeline_id" => %{"type" => "string", "pattern" => @stable_id_pattern},
          "source_timeline_application" => timeline_transition_application_row_json_schema(),
          "source_timeline_integrity" => operational_timeline_row_json_schema(),
          "source_timeline_activity_state" => timeline_activity_state_source_json_schema(),
          "source_timeline_lifecycle_state" => timeline_lifecycle_state_source_json_schema(),
          "source_timeline_activity_precondition_summary" =>
            timeline_activity_precondition_summary_source_json_schema(),
          "source_timeline_preservation" => timeline_preservation_source_json_schema(),
          "timeline_identity" => timeline_identity_json_schema(),
          "timeline_link" => timeline_link_json_schema(),
          "source_activity_context" => activity_context_json_schema(),
          "replacement_activity_context" => activity_context_json_schema(),
          "source_timeline_identity" => timeline_identity_json_schema(),
          "replacement_timeline_identity" => timeline_identity_json_schema(),
          "source_timeline_protection" => timeline_protection_summary_json_schema()
        }
        |> Map.merge(timeline_dependency_impact_handoff_json_schema_properties())
        |> Map.merge(timeline_publication_handoff_json_schema_properties())
        |> Map.merge(timeline_activity_precondition_handoff_json_schema_properties())
        |> Map.merge(command_authority_handoff_json_schema_properties())
        |> Map.merge(feedback_maneuver_handoff_json_schema_properties())
        |> Map.merge(link_handoff_json_schema_properties())
        |> Map.merge(thermal_handoff_json_schema_properties())
        |> Map.merge(resource_availability_variance_json_schema_properties())
        |> Map.merge(
          OrbitalDynamics.Schema.OperationalReadinessContextJsonSchema.resource_context_properties(
            stable_id_pattern: @stable_id_pattern
          )
        )
        |> Map.merge(
          OrbitalDynamics.Schema.OperationalReadinessContextJsonSchema.operator_training_context_properties()
        )
        |> Map.merge(
          OrbitalDynamics.Schema.OperationalReadinessContextJsonSchema.adapter_boundary_context_properties()
        )
        |> Map.merge(resource_projection_battery_handoff_json_schema_properties())
        |> Map.merge(branch_scoped_downlink_context_json_schema_properties())
        |> Map.merge(scoped_downlink_context_json_schema_properties())
    }
  end

  defp maybe_add_const(property, "schema_contract", name, _contract) do
    property
    |> Map.put("const", name)
    |> Map.put("description", "Stable executable contract identifier")
  end

  defp maybe_add_const(property, "schema_version", _name, contract) do
    property
    |> Map.put("const", contract["schema_version"])
    |> Map.put("description", "Artifact schema version")
  end

  defp maybe_add_const(property, "artifact_type", _name, contract) do
    Map.put(property, "const", contract["artifact_family"])
  end

  defp maybe_add_const(property, _field, _name, _contract), do: property

  defp maybe_add_stable_id_pattern(%{"type" => "string"} = property, field) do
    if stable_id_field?(field) do
      Map.put(property, "pattern", @stable_id_pattern)
    else
      property
    end
  end

  defp maybe_add_stable_id_pattern(property, _field), do: property

  defp stable_id_field?(field), do: field == "id" or String.ends_with?(field, "_id")

