  defp validate_accepted_planning_state_counts(issues, artifact) do
    spacecraft_states =
      artifact
      |> Map.get("spacecraft_states", [])
      |> case do
        rows when is_list(rows) -> Enum.filter(rows, &is_map/1)
        _rows -> []
      end

    expect_field_equals(
      issues,
      "$.provenance",
      Map.get(artifact, "provenance", %{}),
