      is_binary(provenance_trust_boundary) and provenance_trust_boundary != "" ->
        issues

      true ->
        [
          error(
            path <> ".trust_boundary",
            "station_calendar_provider.v1 requires trust_boundary or provenance.trust_boundary"
          )
          | issues
        ]
    end
  end

