  defp validate_timeline_transition_application_report(issues, path, report) do
    issues
    |> expect_equal(path, report, "schema_contract", "timeline_transition_application_report.v1")
    |> expect_equal(path, report, "model", "artifact_only_timeline_transition_application")
    |> expect_type(path, report, "source", :binary)
    |> expect_non_negative_integer(path, report, "source_activity_count")
    |> expect_non_negative_integer(path, report, "replacement_activity_count")
    |> expect_non_negative_integer(path, report, "application_count")
    |> expect_non_negative_integer(path, report, "selected_activity_count")
    |> expect_non_negative_integer(path, report, "review_required_count")
    |> expect_optional_non_negative_integer(path, report, "preserved_source_count")
    |> expect_optional_non_negative_integer(path, report, "recorded_replacement_count")
    |> expect_optional_non_negative_integer(path, report, "withheld_review_count")
    |> expect_optional_type(path, report, "application_status_counts", :map)
    |> expect_optional_type(path, report, "transition_decision_counts", :map)
    |> expect_optional_type(path, report, "required_operator_action_counts", :map)
    |> expect_optional_type(path, report, "status_transition_counts", :map)
    |> expect_optional_type(path, report, "approval_transition_counts", :map)
    |> expect_optional_type(path, report, "status_transition_category_counts", :map)
    |> expect_optional_type(path, report, "approval_transition_category_counts", :map)
    |> expect_optional_non_negative_integer(
      path,
      report,
      "selected_timeline_integrity_review_count"
    )
    |> expect_optional_non_negative_integer(
      path,
      report,
      "selected_timeline_integrity_issue_count"
    )
    |> expect_optional_type(path, report, "selected_timeline_integrity_issue_types", :list)
    |> validate_string_list_allowed(
      path,
      report,
      "selected_timeline_integrity_issue_types",
      OrbitalDynamics.Timeline.capabilities().timeline_integrity_issue_types
    )
    |> expect_optional_type(path, report, "model_limits", :list)
    |> validate_string_list_items(path, report, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      report,
      timeline_report_model_limits(),
      "must match timeline report model limits"
    )
    |> expect_optional_type(path, report, "selected_activities", :list)
    |> expect_type(path, report, "applications", :list)
    |> expect_type(path, report, "assumptions", :map)
    |> validate_timeline_transition_application_report_counts(path, report)
    |> validate_optional_rows(
      path <> ".selected_activities",
      Map.get(report, "selected_activities"),
      &validate_timeline_transition_selected_activity/3
    )
    |> validate_rows(
      path <> ".applications",
      Map.get(report, "applications", []),
      &validate_timeline_transition_application_row/3
    )
  end

  defp validate_timeline_transition_application_report_counts(issues, path, report) do
    applications =
      report
      |> Map.get("applications", [])
      |> Enum.filter(&is_map/1)

    selected_activities =
      report
      |> Map.get("selected_activities")
      |> case do
        activities when is_list(activities) -> Enum.filter(activities, &is_map/1)
        _activities -> nil
      end

    issues
    |> validate_non_negative_integer_count_map(
      path <> ".application_status_counts",
      Map.get(report, "application_status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".transition_decision_counts",
      Map.get(report, "transition_decision_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".required_operator_action_counts",
      Map.get(report, "required_operator_action_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".status_transition_counts",
      Map.get(report, "status_transition_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".approval_transition_counts",
      Map.get(report, "approval_transition_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".status_transition_category_counts",
      Map.get(report, "status_transition_category_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".approval_transition_category_counts",
      Map.get(report, "approval_transition_category_counts")
    )
    |> expect_field_equals(path, report, "application_count", length(applications))
    |> expect_field_equals(
      path,
      report,
      "selected_activity_count",
      if(is_list(selected_activities), do: length(selected_activities), else: nil)
    )
    |> expect_field_equals(
      path,
      report,
      "review_required_count",
      Enum.count(applications, &(&1["requires_operator_review"] == true))
    )
    |> expect_field_equals(
      path,
      report,
      "application_status_counts",
      frequency_map(applications, "application_status"),
      "must equal application-derived application_status_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "transition_decision_counts",
      frequency_map(applications, "transition_decision"),
      "must equal application-derived transition_decision_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "required_operator_action_counts",
      frequency_map(applications, "required_operator_action"),
      "must equal application-derived required_operator_action_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "status_transition_counts",
      nested_frequency_map(applications, "status_transition", "transition_type"),
      "must equal application-derived status_transition_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "approval_transition_counts",
      nested_frequency_map(applications, "approval_transition", "transition_type"),
      "must equal application-derived approval_transition_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "status_transition_category_counts",
      nested_frequency_map(applications, "status_transition", "transition_category"),
      "must equal application-derived status_transition_category_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "approval_transition_category_counts",
      nested_frequency_map(applications, "approval_transition", "transition_category"),
      "must equal application-derived approval_transition_category_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "preserved_source_count",
      Enum.count(applications, &(&1["transition_decision"] == "preserve_source"))
    )
    |> expect_field_equals(
      path,
      report,
      "recorded_replacement_count",
      Enum.count(applications, &(&1["selected_activity_source"] == "replacement"))
    )
    |> expect_field_equals(
      path,
      report,
      "withheld_review_count",
      Enum.count(applications, &(&1["application_status"] == "operator_review_required"))
    )
    |> expect_field_equals(
      path,
      report,
      "selected_timeline_integrity_review_count",
      Enum.count(
        selected_activities || [],
        &(&1["timeline_integrity_status"] == "review_required")
      )
    )
    |> expect_field_equals(
      path,
      report,
      "selected_timeline_integrity_issue_count",
      sum_row_numbers(selected_activities || [], "timeline_integrity_issue_count")
    )
    |> expect_field_equals(
      path,
      report,
      "selected_timeline_integrity_issue_types",
      selected_timeline_integrity_issue_types(selected_activities || []),
      "must equal selected-activity-derived selected_timeline_integrity_issue_types"
    )
  end

