  defp resource_projection_flow_summary_pressure_row?(row) do
    Map.get(row, "resource_pressure_types", []) != [] or
      Map.get(row, "resource_pressure_status") in [
        "review_required",
        "storage_overflow",
        "downlink_shortfall",
        "battery_depletion"
      ]
  end

  defp resource_projection_flow_summary_pressure_types(projected_rows, flow_rows) do
    projected_types =
      projected_rows
      |> Enum.flat_map(fn
        %{} = row -> Map.get(row, "resource_pressure_types", [])
        _row -> []
      end)

    flow_types =
      flow_rows
      |> Enum.flat_map(&resource_projection_pressure_kinds/1)

    (projected_types ++ flow_types)
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp resource_projection_flow_summary_ignored_rows(flow_rows) do
    Enum.filter(flow_rows, &(Map.get(&1, "resource_effect_status") == "ignored"))
  end

  defp resource_projection_flow_summary_ignored_activity_ids(rows) do
    rows
    |> Enum.map(&Map.get(&1, "activity_id"))
    |> sorted_stable_values()
  end

  defp resource_projection_flow_summary_ignored_activity_reason_counts(rows) do
    rows
    |> Enum.map(&Map.get(&1, "resource_effect_reason"))
    |> Enum.reject(&is_nil/1)
    |> Enum.frequencies()
  end

  defp resource_projection_flow_summary_ignored_activity_ids_by_reason(rows) do
    rows
    |> Enum.map(&{Map.get(&1, "resource_effect_reason"), Map.get(&1, "activity_id")})
    |> stable_values_by_key()
  end

  defp resource_projection_flow_actual_data_volume_evidence_count(flow_rows) do
    Enum.count(flow_rows, &is_number(Map.get(&1, "actual_data_volume_mb")))
  end

  defp resource_projection_flow_data_volume_variance_activity_ids(flow_rows, variance) do
    flow_rows
    |> Enum.filter(&resource_projection_flow_data_volume_variance?(&1, variance))
    |> Enum.map(&Map.get(&1, "activity_id"))
    |> sorted_stable_values()
  end

  defp resource_projection_flow_data_volume_variance?(row, variance) do
    case Map.get(row, "data_volume_delta_mb") do
      delta when is_number(delta) and variance == :under_delivered -> delta < 0.0
      delta when is_number(delta) and variance == :over_delivered -> delta > 0.0
      delta when is_number(delta) and variance == :exact -> delta == 0.0
      _delta -> false
    end
  end

  defp resource_projection_flow_summary_spacecraft_ids_by_type(projected_rows, flow_rows) do
    projected_pairs =
      Enum.flat_map(projected_rows, fn
        %{} = row ->
          row
          |> Map.get("resource_pressure_types", [])
          |> Enum.map(&{&1, Map.get(row, "spacecraft_id")})

        _row ->
          []
      end)

    flow_pairs =
      Enum.flat_map(flow_rows, fn row ->
        Enum.map(resource_projection_pressure_kinds(row), &{&1, Map.get(row, "spacecraft_id")})
      end)

    stable_values_by_key(projected_pairs ++ flow_pairs)
  end

  defp resource_projection_pressure_ground_station_ids_by_type(flow_rows) do
    flow_rows
    |> Enum.flat_map(fn
      %{} = row ->
        Enum.map(resource_projection_pressure_kinds(row), fn pressure_type ->
          {pressure_type, Map.get(row, "ground_station_id")}
        end)

      _row ->
        []
    end)
    |> stable_values_by_key()
  end

  defp resource_projection_pressure_source_window_ids_by_type(flow_rows) do
    flow_rows
    |> Enum.flat_map(fn
      %{} = row ->
        Enum.map(resource_projection_pressure_kinds(row), fn pressure_type ->
          {pressure_type, Map.get(row, "source_window_id")}
        end)

      _row ->
        []
    end)
    |> stable_values_by_key()
  end

  defp resource_projection_pressure_station_calendar_entry_ids_by_type(flow_rows) do
    flow_rows
    |> Enum.flat_map(fn
      %{} = row ->
        Enum.map(resource_projection_pressure_kinds(row), fn pressure_type ->
          {pressure_type, Map.get(row, "station_calendar_entry_id")}
        end)

      _row ->
        []
