  defp validate_cadence_import_manifest_assumptions(issues, path, manifest) do
    case Map.get(manifest, "assumptions") do
      %{} = assumptions ->
        [
          {"execution_boundary", "artifact_only_no_cadence_api_writes"},
          {"authorization_boundary", "operator_review_or_cadence_adapter_must_authorize_import"}
        ]
        |> Enum.reduce(issues, fn {field, expected}, acc ->
          if Map.has_key?(assumptions, field) and Map.get(assumptions, field) != expected do
            [error("#{path}.assumptions.#{field}", "must equal #{inspect(expected)}") | acc]
          else
            acc
          end
        end)

      _assumptions ->
        issues
    end
  end

  defp validate_cadence_import_manifest_scalar_counts(issues, path, manifest) do
    Enum.reduce(@cadence_import_manifest_scalar_count_fields, issues, fn field, acc ->
      expect_non_negative_integer(acc, path, manifest, field)
    end)
