  defp validate_operational_readiness_report(issues, path, report) do
    gates = Map.get(report, "gates", [])
    evidence = Map.get(report, "evidence", %{})
    capability = OrbitalDynamics.OperationalReadiness.capabilities()

    issues
    |> expect_equal(path, report, "schema_contract", "operational_readiness_report.v1")
    |> expect_equal(path, report, "model", "artifact_only_operational_readiness_classifier")
    |> validate_stable_ids(path, report, ["report_id", "source_artifact_id"])
    |> expect_one_of(path, report, "readiness_level", capability.readiness_levels)
    |> expect_one_of(path, report, "import_classification", capability.import_classifications)
    |> expect_one_of(path, report, "status", capability.gate_statuses)
    |> expect_non_negative_integer(path, report, "gate_count")
    |> expect_non_negative_integer(path, report, "passed_gate_count")
    |> expect_non_negative_integer(path, report, "review_gate_count")
    |> expect_non_negative_integer(path, report, "analysis_gate_count")
    |> expect_non_negative_integer(path, report, "blocked_gate_count")
    |> expect_type(path, report, "gates", :list)
    |> validate_rows(path <> ".gates", gates, &validate_operational_readiness_gate/3)
    |> expect_type(path, report, "evidence", :map)
    |> validate_operational_readiness_evidence(path <> ".evidence", evidence)
    |> expect_type(path, report, "assumptions", :list)
    |> validate_string_list_items(path, report, "assumptions")
    |> expect_type(path, report, "model_limits", :list)
    |> validate_string_list_items(path, report, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      report,
      operational_readiness_model_limits(),
      "must match operational readiness model limits"
    )
    |> validate_operational_readiness_assumptions(path, report)
    |> validate_operational_readiness_classification(path, report, gates)
    |> validate_operational_readiness_evidence_gate_counts(path <> ".evidence", evidence, gates)
    |> expect_field_equals(path, report, "gate_count", if(is_list(gates), do: length(gates)))
    |> expect_field_equals(
      path,
      report,
      "passed_gate_count",
      gate_status_count(gates, "passed")
    )
    |> expect_field_equals(
      path,
      report,
      "review_gate_count",
      gate_status_count(gates, "review_required")
    )
    |> expect_field_equals(
      path,
      report,
      "analysis_gate_count",
      gate_status_count(gates, "analysis_only")
    )
    |> expect_field_equals(
      path,
      report,
      "blocked_gate_count",
      gate_status_count(gates, "blocked")
    )
  end

  defp validate_operational_readiness_assumptions(issues, path, report) do
    assumptions = Map.get(report, "assumptions")

    required_assumptions = [
      "classification_uses_declared_operator_review_and_cadence_import_manifest_evidence",
      "cadence_import_manifest_rows_are_adapter_handoff_not_external_import_writes"
    ]

    if is_list(assumptions) and Enum.all?(required_assumptions, &(&1 in assumptions)) do
      issues
    else
      [
        error(
          path <> ".assumptions",
          "must include operational readiness artifact-only assumptions"
        )
        | issues
      ]
    end
  end

