    |> expect_field_equals(
      path,
      report,
      "readiness_level",
      readiness_level,
      "must match gate-derived readiness level"
    )
    |> expect_field_equals(
      path,
      report,
      "status",
      status,
      "must match gate-derived report status"
    )
  end

  defp validate_operational_readiness_classification(issues, _path, _report, _gates),
    do: issues

  defp operational_readiness_import_classification(gates) do
    statuses =
      gates
      |> Enum.filter(&is_map/1)
      |> Enum.map(&Map.get(&1, "status"))

    cond do
      "blocked" in statuses -> "blocked"
      "analysis_only" in statuses -> "analysis_only"
      "review_required" in statuses -> "review_only"
      true -> "importable"
    end
  end

  defp operational_readiness_level("importable"), do: "import_eligible"
  defp operational_readiness_level("review_only"), do: "operator_review"
  defp operational_readiness_level("analysis_only"), do: "analysis_only"
  defp operational_readiness_level("blocked"), do: "blocked"

