  defp quality_gate_ids(rows, status) when is_list(rows) do
    rows
    |> Enum.filter(&is_map/1)
    |> Enum.filter(&(Map.get(&1, "status") == status))
    |> Enum.map(&Map.get(&1, "gate_id"))
    |> stable_sorted_ids()
  end

