  defp validate_freshness_source_status_matches(
         issues,
         path,
         %{"source_freshness_report" => %{} = source_report} = row
       ) do
    row_status = Map.get(row, "freshness_status")
    source_status = Map.get(source_report, "status")

    issues =
      if is_binary(source_status) and source_status not in freshness_statuses() do
        [
          error(
            "#{path}.source_freshness_report.status",
            "must be one of current, stale, unknown"
          )
          | issues
        ]
      else
        issues
      end

    if is_binary(row_status) and is_binary(source_status) and row_status != source_status,
      do: [
        error("#{path}.source_freshness_report.status", "must match freshness_status") | issues
      ],
      else: issues
  end

