  defp validate_suppression_duplicate_handoff_row_fields(issues, path, row) do
    if suppression_duplicate_handoff_row?(row) do
      issues
      |> expect_optional_type(path, row, "duplicate_suppressed_candidate_id_collision", :boolean)
      |> expect_optional_integer(path, row, "duplicate_suppressed_candidate_index")
      |> expect_field_at_least(path, row, "duplicate_suppressed_candidate_index", 0)
      |> expect_optional_integer(path, row, "duplicate_suppressed_candidate_count")
      |> expect_field_at_least(path, row, "duplicate_suppressed_candidate_count", 0)
      |> validate_duplicate_suppressed_candidate_evidence(path, row)
    else
      issues
    end
  end

  defp suppression_duplicate_handoff_row?(row) do
    Map.get(row, "review_type") in ["contact_suppression", "resource_suppression"] or
      Map.get(row, "source_review_type") in ["contact_suppression", "resource_suppression"] or
