  defp validate_validation_safety_case_branch_event_status(
         issues,
         path,
         %{"type" => "validation_safety_case_pressure"} = event
       ) do
    issues
    |> require_fields(path, event, ["evidence_status"])
    |> expect_optional_one_of(path, event, "validation_safety_case_status", [
      "review_required",
      "blocked"
    ])
    |> expect_optional_one_of(path, event, "evidence_status", [
      "review_required",
      "blocked"
    ])
  end

  defp validate_validation_safety_case_branch_event_status(issues, _path, _event), do: issues

  defp validate_validation_safety_case_branch_event_action(
         issues,
         path,
         %{"type" => "validation_safety_case_pressure"} = event
       ) do
    expected_action =
      if event["evidence_status"] == "blocked" or
           event["validation_safety_case_status"] == "blocked" do
        "review_blocked_validation_safety_case"
      else
        "review_validation_safety_case"
      end

    expect_equal(issues, path, event, "required_operator_action", expected_action)
  end

  defp validate_validation_safety_case_branch_event_action(issues, _path, _event), do: issues

  defp validate_recommendation(issues, path, recommendation) do
    issues
    |> require_fields(path, recommendation, [
      "recommended_branch_id",
      "approval_status",
      "reason",
      "ranked_branch_ids",
      "tradeoffs",
      "explanation",
      "risks_remaining",
      "requires_approval"
    ])
    |> validate_stable_ids(path, recommendation, ["recommended_branch_id"])
    |> validate_stable_id_list(
      path <> ".ranked_branch_ids",
      Map.get(recommendation, "ranked_branch_ids")
    )
    |> validate_optional_schema_contract(path, recommendation, "strategy_recommendation.v1")
    |> expect_optional_type(path, recommendation, "status", :binary)
    |> expect_type(path, recommendation, "ranked_branch_ids", :list)
    |> expect_type(path, recommendation, "tradeoffs", :list)
    |> expect_type(path, recommendation, "requires_approval", :list)
    |> expect_type(path, recommendation, "explanation", :list)
    |> validate_recommendation_consistency(path, recommendation)
    |> validate_optional_rows(
      path <> ".tradeoffs",
      Map.get(recommendation, "tradeoffs"),
      &validate_strategy_tradeoff/3
    )
    |> validate_optional_rows(
      path <> ".explanation",
      Map.get(recommendation, "explanation"),
      &validate_strategy_explanation/3
    )
    |> validate_optional_rows(
      path <> ".risks_remaining",
      Map.get(recommendation, "risks_remaining"),
      &validate_strategy_risk/3
    )
  end

  defp validate_recommendation_consistency(issues, path, recommendation) do
    recommended_branch_id = Map.get(recommendation, "recommended_branch_id")

    issues
    |> validate_recommendation_ranked_branch(path, recommendation, recommended_branch_id)
    |> validate_recommendation_explanation_branch_ids(path, recommendation, recommended_branch_id)
    |> validate_recommendation_approval_requirements(path, recommendation)
  end

  defp validate_recommendation_ranked_branch(
         issues,
         _path,
         %{"ranked_branch_ids" => [recommended_branch_id | _ids]},
         recommended_branch_id
       )
       when is_binary(recommended_branch_id),
       do: issues

  defp validate_recommendation_ranked_branch(
         issues,
         path,
         %{"ranked_branch_ids" => ids},
         recommended_branch_id
       )
       when is_list(ids) and is_binary(recommended_branch_id) do
    [error(path <> ".recommended_branch_id", "must be first in ranked_branch_ids") | issues]
  end

  defp validate_recommendation_ranked_branch(
         issues,
         _path,
         _recommendation,
         _recommended_branch_id
       ),
       do: issues

  defp validate_recommendation_explanation_branch_ids(
         issues,
         path,
         %{"explanation" => explanation},
         recommended_branch_id
       )
       when is_list(explanation) and is_binary(recommended_branch_id) do
    explanation
    |> Enum.with_index()
    |> Enum.reduce(issues, fn {row, index}, acc ->
      case row do
        %{"recommended_branch_id" => ^recommended_branch_id} ->
          acc

        %{"recommended_branch_id" => _other_branch_id} ->
          [
            error(
              "#{path}.explanation[#{index}].recommended_branch_id",
              "must match top-level recommended_branch_id"
            )
            | acc
          ]

        _row ->
          acc
      end
    end)
  end

  defp validate_recommendation_explanation_branch_ids(
         issues,
         _path,
         _recommendation,
         _recommended_branch_id
       ),
       do: issues

  defp validate_recommendation_approval_requirements(issues, path, %{
         "approval_status" => approval_status,
         "requires_approval" => rows
       })
       when is_binary(approval_status) and is_list(rows) do
    rows
    |> Enum.with_index()
    |> Enum.reduce(issues, fn {row, index}, acc ->
      case row do
        %{"policy_classification" => ^approval_status} ->
          acc

        %{"policy_classification" => _other_classification} ->
          [
            error(
              "#{path}.requires_approval[#{index}].policy_classification",
              "must match recommendation approval_status"
            )
            | acc
          ]

        _row ->
          acc
      end
    end)
  end

  defp validate_recommendation_approval_requirements(issues, _path, _recommendation), do: issues

  defp validate_strategy_tradeoff(issues, path, row) do
    issues
    |> require_fields(path, row, ["dimension", "baseline", "recommended", "delta"])
    |> expect_type(path, row, "dimension", :binary)
    |> expect_number(path, row, "baseline")
    |> expect_number(path, row, "recommended")
    |> expect_number(path, row, "delta")
    |> validate_strategy_tradeoff_delta(path, row)
  end

  defp validate_strategy_tradeoff_delta(
         issues,
         path,
         %{"baseline" => baseline, "recommended" => recommended, "delta" => delta}
       )
       when is_number(baseline) and is_number(recommended) and is_number(delta) do
    if abs(delta - (recommended - baseline)) <= 1.0e-9 do
      issues
    else
      [error(path <> ".delta", "must equal recommended minus baseline") | issues]
    end
  end

  defp validate_strategy_tradeoff_delta(issues, _path, _row), do: issues

  defp validate_strategy_explanation(issues, path, row) do
    issues
    |> require_fields(path, row, ["type"])
    |> validate_branch_event_summary_fields(path, row)
  end

  defp validate_strategy_risk(issues, path, risk) do
    issues
    |> require_fields(path, risk, ["type", "severity", "reason"])
    |> validate_scoped_downlink_context_fields(path, risk)
  end

  defp validate_policy_decision(issues, path, decision) do
    issues
    |> require_fields(path, decision, ["schema_contract", "classification"])
    |> validate_stable_ids(path, decision, ["policy_bundle_id"])
    |> expect_equal(path, decision, "schema_contract", "policy_decision.v1")
    |> expect_one_of(path, decision, "classification", [
      "auto_approvable",
      "operator_review_required",
      "blocked_by_policy"
    ])
    |> expect_optional_list(path, decision, "rule_matches")
    |> validate_optional_rows(
      path <> ".rule_matches",
      Map.get(decision, "rule_matches"),
      &validate_policy_rule_match/3
    )
    |> expect_optional_list(path, decision, "escalations")
    |> validate_optional_rows(
      path <> ".escalations",
      Map.get(decision, "escalations"),
      &validate_policy_escalation/3
    )
    |> expect_optional_non_negative_integer(path, decision, "approval_requirement_count")
    |> expect_optional_non_negative_integer(path, decision, "risk_count")
    |> expect_optional_type(path, decision, "assumptions", :map)
    |> expect_optional_type(path, decision, "model_limits", :list)
    |> validate_string_list_items(path, decision, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      decision,
      policy_model_limits(),
      "must match policy model limits"
    )
    |> validate_policy_decision_counts(path, decision)
  end

  defp validate_policy_decision_counts(issues, path, decision) do
    rule_matches = Map.get(decision, "rule_matches")

    issues
    |> expect_field_equals(
      path,
      decision,
      "classification",
      policy_decision_classification(rule_matches)
    )
    |> expect_field_equals(
      path,
      decision,
      "approval_requirement_count",
      policy_decision_approval_requirement_count(rule_matches)
    )
    |> expect_field_equals(path, decision, "risk_count", policy_decision_risk_count(rule_matches))
    |> validate_policy_decision_escalation_rule_ids(path, decision)
  end

  defp policy_decision_classification(rule_matches) when is_list(rule_matches) do
    cond do
      Enum.any?(rule_matches, &policy_rule_match_classification?(&1, "blocked_by_policy")) ->
        "blocked_by_policy"

      Enum.any?(rule_matches, &policy_rule_match_classification?(&1, "operator_review_required")) ->
        "operator_review_required"

      Enum.any?(rule_matches, &policy_rule_match_classification?(&1, "auto_approvable")) ->
        "auto_approvable"

      true ->
        nil
    end
  end

  defp policy_decision_classification(_rule_matches), do: nil

  defp policy_decision_approval_requirement_count(rule_matches)
       when is_list(rule_matches) and rule_matches != [] do
    Enum.count(rule_matches, &policy_rule_match_classification?(&1, "operator_review_required"))
  end

  defp policy_decision_approval_requirement_count(_rule_matches), do: nil

  defp policy_decision_risk_count(rule_matches)
       when is_list(rule_matches) and rule_matches != [] do
    Enum.count(rule_matches, &(is_map(&1) and is_binary(Map.get(&1, "risk_type"))))
  end

  defp policy_decision_risk_count(_rule_matches), do: nil

  defp policy_rule_match_classification?(match, classification) when is_map(match) do
    Map.get(match, "classification") == classification
  end

  defp policy_rule_match_classification?(_match, _classification), do: false

  defp validate_policy_decision_escalation_rule_ids(issues, path, decision) do
    rule_matches = Map.get(decision, "rule_matches")
    escalations = Map.get(decision, "escalations")

    if is_list(rule_matches) and rule_matches != [] and is_list(escalations) do
      rule_ids =
        rule_matches
        |> Enum.map(&if(is_map(&1), do: Map.get(&1, "rule_id")))
        |> Enum.reject(&is_nil/1)
        |> MapSet.new()

      stale_escalation? =
        Enum.any?(escalations, fn
          %{} = escalation ->
            rule_id = Map.get(escalation, "rule_id")
            is_binary(rule_id) and not MapSet.member?(rule_ids, rule_id)

          _escalation ->
            false
        end)

      if stale_escalation? do
        [error(path <> ".escalations", "must reference rule_matches rule_id values") | issues]
      else
        issues
      end
    else
      issues
    end
  end

  defp validate_policy_rule_match(issues, path, match) do
    issues
    |> validate_stable_ids(path, match, ["rule_id", "activity_id"])
    |> validate_optional_string_fields(path, match, @policy_context_string_fields)
    |> validate_optional_string_lists(path, match, @policy_context_string_array_fields)
    |> validate_optional_string_or_array_fields(
      path,
      match,
      @policy_context_string_or_array_fields
    )
    |> validate_optional_number_fields(path, match, @policy_context_number_fields)
    |> expect_optional_type(path, match, "station_calendar_reservation_expires_at_s", :list)
    |> validate_number_list_items(path, match, "station_calendar_reservation_expires_at_s")
    |> validate_optional_integer_fields(path, match, @policy_context_integer_fields)
    |> validate_optional_boolean_fields(path, match, @policy_context_boolean_fields)
    |> expect_optional_one_of(path, match, "classification", [
      "auto_approvable",
      "operator_review_required",
      "blocked_by_policy"
    ])
    |> expect_optional_type(path, match, "reason", :binary)
    |> expect_optional_type(path, match, "action", :binary)
    |> expect_optional_type(path, match, "activity_type", :binary)
    |> expect_optional_type(path, match, "requirement_type", :binary)
    |> expect_optional_type(path, match, "direction", :binary)
    |> expect_optional_type(path, match, "ground_station_id", :binary)
    |> expect_optional_type(path, match, "station_contention_status", :binary)
    |> expect_optional_type(path, match, "station_reservation_status", :binary)
    |> expect_optional_number(path, match, "contention_window_s")
