  end

  defp validate_policy_escalation(issues, path, escalation) do
    issues
    |> validate_stable_ids(path, escalation, ["rule_id"])
    |> expect_optional_type(path, escalation, "rule_id", :binary)
    |> expect_optional_one_of(path, escalation, "classification", [
      "auto_approvable",
      "operator_review_required",
      "blocked_by_policy"
    ])
    |> expect_optional_type(path, escalation, "escalation_level", :binary)
    |> expect_optional_type(path, escalation, "escalation_queue", :binary)
    |> expect_optional_type(path, escalation, "escalation_role", :binary)
    |> expect_optional_type(path, escalation, "required_authority", :binary)
    |> expect_optional_number(path, escalation, "sla_s")
  end

  defp validate_policy_bundle(issues, path, bundle) do
    approval_policy = Map.get(bundle, "approval_policy", %{})

    issues
    |> validate_stable_ids(path, bundle, ["id"])
    |> expect_equal(path, bundle, "schema_contract", "policy_bundle.v1")
    |> expect_type(path, bundle, "approval_policy", :map)
    |> expect_optional_type(path, bundle, "provenance", :map)
    |> expect_optional_type(path, bundle, "assumptions", :map)
    |> expect_optional_type(path, bundle, "model_limits", :list)
    |> validate_string_list_items(path, bundle, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      bundle,
      policy_model_limits(),
      "must match policy model limits"
    )
    |> validate_policy_bundle_provenance(path, bundle)
    |> validate_policy_bundle_assumptions(path, bundle)
    |> validate_approval_policy(path <> ".approval_policy", approval_policy)
  end

  defp validate_policy_bundle_provenance(issues, path, bundle) do
    bundle_id = Map.get(bundle, "id")
    provenance_bundle_id = get_in(bundle, ["provenance", "bundle_id"])

    if is_binary(bundle_id) and is_binary(provenance_bundle_id) and
         provenance_bundle_id != bundle_id do
      [error(path <> ".provenance.bundle_id", "must match bundle id") | issues]
    else
      issues
    end
  end

  defp validate_policy_bundle_assumptions(issues, path, bundle) do
    case Map.get(bundle, "assumptions") do
      %{} = assumptions ->
        [
          {"boundary", "artifact_only_no_authority_lookup"},
          {"workflow_execution", "none"}
        ]
        |> Enum.reduce(issues, fn {field, expected}, acc ->
          if Map.has_key?(assumptions, field) and Map.get(assumptions, field) != expected do
            [error("#{path}.assumptions.#{field}", "must equal #{inspect(expected)}") | acc]
          else
            acc
          end
        end)

      _assumptions ->
        issues
    end
  end

  defp validate_operator_review_package(issues, path, package) do
    issues
    |> expect_equal(path, package, "schema_contract", "operator_review_package.v1")
    |> expect_equal(path, package, "model", "artifact_only_operator_review_package")
    |> expect_one_of(
      path,
      package,
      "source_artifact_type",
      OrbitalDynamics.OperatorReview.capabilities().source_artifact_types
    )
    |> validate_stable_ids(path, package, ["source_artifact_id"])
    |> validate_operator_review_package_scalar_counts(path, package)
    |> expect_optional_type(path, package, "review_type_counts", :map)
    |> expect_optional_type(path, package, "review_queue_counts", :map)
    |> expect_optional_type(path, package, "approval_status_counts", :map)
    |> expect_optional_type(path, package, "required_operator_action_counts", :map)
    |> expect_optional_type(path, package, "cadence_import_status_counts", :map)
    |> expect_optional_type(path, package, "source_cadence_import_status_counts", :map)
    |> expect_optional_type(path, package, "replacement_cadence_import_status_counts", :map)
    |> expect_optional_type(path, package, "calendar_entry_trust_boundary_status_counts", :map)
    |> expect_optional_type(path, package, "station_reservation_ids", :list)
    |> validate_optional_stable_id_list(path, package, "station_reservation_ids")
    |> expect_optional_type(path, package, "station_reserved_bys", :list)
    |> validate_string_list_items(path, package, "station_reserved_bys")
    |> expect_optional_type(path, package, "station_reservation_statuses", :list)
    |> validate_string_list_items(path, package, "station_reservation_statuses")
    |> expect_optional_type(path, package, "station_reservation_match_status_counts", :map)
    |> validate_contact_allocation_expiration_handoff_summary(path, package)
    |> validate_quality_gate_handoff_summary(path, package)
    |> expect_optional_type(path, package, "model_limits", :list)
    |> validate_string_list_items(path, package, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      package,
      operator_review_package_model_limits(),
      "must match operator review package model limits"
    )
    |> validate_operator_review_package_assumptions(path, package)
    |> expect_type(path, package, "rows", :list)
    |> expect_type(path, package, "provenance", :map)
    |> expect_type(path, package, "assumptions", :map)
    |> validate_rows(
      path <> ".rows",
      Map.get(package, "rows", []),
      &validate_operator_review_row/3
    )
    |> validate_suppression_duplicate_handoff_groups(path, Map.get(package, "rows", []))
    |> validate_operator_review_package_counts(path, package)
  end

  defp validate_operator_review_package_assumptions(issues, path, package) do
    case Map.get(package, "assumptions") do
      %{} = assumptions ->
        if Map.has_key?(assumptions, "boundary") and
             Map.get(assumptions, "boundary") != "artifact_only_no_api_or_database_writes" do
          [
            error(
              path <> ".assumptions.boundary",
              "must equal \"artifact_only_no_api_or_database_writes\""
            )
            | issues
          ]
        else
          issues
        end

      _assumptions ->
        issues
    end
  end

  defp validate_operator_review_package_scalar_counts(issues, path, package) do
    issues =
      Enum.reduce(@operator_review_package_required_scalar_count_fields, issues, fn field, acc ->
        expect_non_negative_integer(acc, path, package, field)
      end)

    Enum.reduce(@operator_review_package_optional_scalar_count_fields, issues, fn field, acc ->
      expect_optional_non_negative_integer(acc, path, package, field)
    end)
  end

