    |> expect_optional_number(path, rule, "capacity_fraction_max")
    |> expect_optional_number(path, rule, "actual_completion_fraction_max")
    |> expect_optional_probability(path, rule, "command_success_factor_max")
    |> expect_optional_probability(path, rule, "contact_success_factor_max")
    |> expect_optional_probability(path, rule, "observation_success_factor_max")
