    |> expect_optional_number(path, rule, "total_contact_duration_s_min")
    |> expect_field_at_least(path, rule, "total_contact_duration_s_min", 0)
    |> expect_optional_number(path, rule, "overlap_duration_s_min")
    |> expect_field_at_least(path, rule, "overlap_duration_s_min", 0)
    |> expect_optional_integer(path, rule, "max_concurrent_contacts_min")
    |> expect_field_at_least(path, rule, "max_concurrent_contacts_min", 0)
    |> expect_optional_integer(path, rule, "overlap_contact_pair_count_min")
    |> expect_field_at_least(path, rule, "overlap_contact_pair_count_min", 0)
    |> expect_optional_type(path, rule, "priority_field_without_numeric_evidence", :binary)
    |> expect_optional_integer(path, rule, "priority_fields_without_numeric_evidence_count_min")
    |> expect_field_at_least(
      path,
      rule,
      "priority_fields_without_numeric_evidence_count_min",
      0
    )
    |> expect_optional_type(path, rule, "priority_fields_without_numeric_evidence", :list)
    |> validate_string_list_items(path, rule, "priority_fields_without_numeric_evidence")
    |> expect_optional_type(path, rule, "station_calendar_trust_boundary_status", :binary)
    |> expect_optional_type(path, rule, "escalation_level", :binary)
    |> expect_optional_type(path, rule, "escalation_queue", :binary)
    |> expect_optional_type(path, rule, "escalation_role", :binary)
    |> expect_optional_type(path, rule, "required_authority", :binary)
    |> expect_optional_number(path, rule, "sla_s")
    |> validate_policy_action_rule_escalation_authority(path, rule)
  end

  defp validate_policy_action_rule_escalation_authority(issues, path, rule) do
    escalation_fields = [
      "escalation_level",
      "escalation_queue",
      "escalation_role",
      "sla_s"
    ]

    has_escalation_metadata? = Enum.any?(escalation_fields, &Map.has_key?(rule, &1))

    if has_escalation_metadata? and not is_binary(Map.get(rule, "required_authority")) do
      [
        error(path <> ".required_authority", "is required when escalation metadata is present")
        | issues
      ]
    else
      issues
    end
  end

