  defp validate_protection_decision(issues, path, decision) do
    issues
    |> validate_stable_ids(path, decision, ["activity_id", "timeline_id"])
    |> expect_optional_type(path, decision, "status", :binary)
    |> expect_optional_type(path, decision, "approval_status", :binary)
    |> expect_optional_type(path, decision, "locked", :boolean)
    |> expect_optional_type(path, decision, "approved", :boolean)
