      "import_adapter",
      :binary
    )
    |> expect_optional_type(
      path <> ".source_event_provenance",
      provenance,
      "trust_boundary",
      :binary
    )
    |> expect_optional_type(
      path <> ".source_event_provenance",
      provenance,
      "trust_boundary_status",
      :binary
    )
  end

  defp validate_activity_context_source_event_provenance(issues, _path, _context), do: issues

